using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
namespace Mcrf.Wpf {
 public sealed partial class MainWindow {
  UIElement DeploymentProfiles(ComboBox recipe,out Func<DeployProvisionOptions> read,bool existing=false){
   var section=new StackPanel{Name="deployProfilesSection",Margin=new Thickness(0,16,0,0)};
   var connectionName=new TextBox{Name="deployConnectionName",MaxLength=80,ToolTip="Свое имя для нового подключения. Один протокол можно создавать несколько раз."};section.Children.Add(DeployField("Название подключения · необязательно",connectionName));
   var create=new CheckBox{Name="deployCreateProfiles",Content=existing?"Создать новое подключение":"Создать подключения после установки",IsChecked=true,IsEnabled=!existing,Margin=new Thickness(0,14,0,16)};section.Children.Add(create);
   var tcp=new CheckBox{Name="deployTcp",Content="TCP · REALITY",IsChecked=true,Style=(Style)FindResource("LabeledPacketCheck"),VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0)};
   var grpc=new CheckBox{Name="deployGrpc",Content="gRPC · REALITY",IsChecked=true,Style=(Style)FindResource("LabeledPacketCheck"),VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0)};
   var tcpPort=new TextBox{Name="deployTcpPort",Text=SuggestedDeploymentPort(12325).ToString()};var grpcPort=new TextBox{Name="deployGrpcPort",Text=SuggestedDeploymentPort(15931).ToString()};var sni=new TextBox{Name="deployRealitySni",Text="pinterest.com"};var service=new TextBox{Name="deployGrpcService",ToolTip="Можно оставить пустым, как в вашем примере."};
   var vpn=new StackPanel();vpn.Children.Add(DeployFields(new UIElement[]{DeployField("Протокол TCP",tcp),DeployField("Порт TCP",tcpPort),DeployField("Протокол gRPC",grpc),DeployField("Порт gRPC",grpcPort)},new[]{-1d,90d,-1d,90d}));vpn.Children.Add(DeployFields(new[]{DeployField("Домен REALITY (SNI)",sni),DeployField("Имя gRPC · необязательно",service)},new[]{-1d,-1d}));vpn.Children.Add(Text("Без домена панель получит самоподписанный HTTPS-сертификат; его отпечаток будет в результате.",12));
   Action modes=()=>{tcpPort.IsEnabled=tcp.IsChecked==true;grpcPort.IsEnabled=service.IsEnabled=grpc.IsChecked==true;};tcp.Checked+=(s,e)=>modes();tcp.Unchecked+=(s,e)=>modes();grpc.Checked+=(s,e)=>modes();grpc.Unchecked+=(s,e)=>modes();modes();
   var transports=new[]{new Choice{Key="direct",Label="Direct · прямой"},new Choice{Key="yandex",Label="Yandex Documents"},new Choice{Key="vyandex",Label="VYandex"},new Choice{Key="boards",Label="Yandex Boards"},new Choice{Key="telemost",Label="Telemost"},new Choice{Key="mailru",Label="Mail.ru Documents"},new Choice{Key="cupsonline",Label="Cups.online"}};
   var transport=new ComboBox{Name="deployOpenfluxTransport",ItemsSource=transports,SelectedIndex=0};var carrier=new TextBox{Name="deployOpenfluxUrl"};var directPort=new TextBox{Name="deployOpenfluxPort",Text=SuggestedDeploymentPort(5443).ToString()};var directField=DeployField("Порт Direct",directPort);var carrierField=DeployField("Ссылка сервиса",carrier);var ofHint=Text("",12);var flux=new StackPanel();flux.Children.Add(DeployFields(new[]{DeployField("Транспорт OpenFlux",transport),directField},new[]{-1d,110d}));flux.Children.Add(carrierField);flux.Children.Add(ofHint);
   Action carrierMode=()=>{string kind=((Choice)transport.SelectedItem).Key;directField.Visibility=kind=="direct"?Visibility.Visible:Visibility.Collapsed;carrierField.Visibility=kind=="direct"||kind=="cupsonline"?Visibility.Collapsed:Visibility.Visible;ofHint.Text=kind=="direct"?"Прямой выход на сервер. Панель выдаст готовую ссылку OpenFlux.":kind=="cupsonline"?"Панель автоматически создаст комнаты и включит их код в подключение.":kind=="telemost"?"Вставьте ссылку отдельной конференции Telemost. Транспорт экспериментальный.":kind=="boards"?"Нужна публичная ссылка на доску с разрешённым гостевым доступом.":"Вставьте публичную ссылку сервиса. Если Yandex потребует вход, настройку нужно подтвердить в панели.";};transport.SelectionChanged+=(s,e)=>carrierMode();carrierMode();
   var kinds=new[]{new Choice{Key="qwdtt",Label="QWDTT · QUIC"},new Choice{Key="wdtt",Label="WDTT Plus · DTLS"},new Choice{Key="csqtt21",Label="CSQTT 2.1"},new Choice{Key="csqtt",Label="CSQTT 2.5"}};var relay=new ComboBox{Name="deploySwgProtocol",ItemsSource=kinds,SelectedIndex=0};var relayPort=new TextBox{Name="deploySwgPort",Text="56000"};var wgPort=new TextBox{Name="deploySwgWgPort",Text="51820"};var wgField=DeployField("Порт WireGuard",wgPort);Func<string[]> readCalls;Action<string[]> replaceCalls;var calls=VkCallFields(out readCalls,out replaceCalls);var vk=AsyncButton("Создать 6 звонков VK",async()=>{var created=await CreateVkCalls(6,replaceCalls);if(created!=null){replaceCalls(created);status.Text="Создано звонков VK: "+created.Length+". Они будут привязаны при деплое SWG.";}});vk.Name="deployVkLogin";vk.MinWidth=195;vk.Margin=new Thickness(0,8,0,8);
   var swg=new StackPanel();swg.Children.Add(DeployFields(new[]{DeployField("Протокол SWG",relay),DeployField("Порт TURN",relayPort),wgField},new[]{-1d,100d,120d}));swg.Children.Add(DeployField("Звонки VK",calls));swg.Children.Add(vk);swg.Children.Add(Text("Звонки привяжутся к подключению. Движок скачивается отдельно в «Обновлениях».",12));relay.SelectionChanged+=(s,e)=>{var choice=relay.SelectedItem as Choice;wgField.Visibility=choice==null||choice.Key.StartsWith("csqtt",StringComparison.Ordinal)?Visibility.Collapsed:Visibility.Visible;};
   section.Children.Add(vpn);section.Children.Add(flux);section.Children.Add(swg);Action selected=()=>{var choice=recipe.SelectedItem as DeployRecipe;string id=choice==null?null:choice.Id;vpn.Visibility=create.IsChecked==true&&id=="3xui"?Visibility.Visible:Visibility.Collapsed;flux.Visibility=create.IsChecked==true&&id=="openflux"?Visibility.Visible:Visibility.Collapsed;swg.Visibility=create.IsChecked==true&&id=="swg"?Visibility.Visible:Visibility.Collapsed;};recipe.SelectionChanged+=(s,e)=>selected();create.Checked+=(s,e)=>selected();create.Unchecked+=(s,e)=>selected();selected();
   read=()=>{var panelChoice=recipe.SelectedItem as DeployRecipe;if(panelChoice==null)throw new FormatException("Выберите тип панели.");string id=panelChoice.Id;var relayChoice=relay.SelectedItem as Choice;string swgChoice=relayChoice==null?"":relayChoice.Key;var carrierChoice=transport.SelectedItem as Choice;var options=new DeployProvisionOptions{create=create.IsChecked==true,connection_name=connectionName.Text.Trim(),tcp=tcp.IsChecked==true,grpc=grpc.IsChecked==true,sni=sni.Text.Trim(),grpc_service=service.Text.Trim(),transport=carrierChoice==null?"":carrierChoice.Key,carrier_url=carrier.Text.Trim(),relay_kind=swgChoice=="csqtt21"?"csqtt":swgChoice,csqtt_line=swgChoice=="csqtt21"?"2.1":"2.5",vk_call=""};if(!options.create)return options;if(connectionName.Text.Any(Char.IsControl))throw new FormatException("Название подключения — без управляющих символов.");if(id=="swg"&&relayChoice==null)throw new FormatException("Выберите протокол SWG.");
    Func<TextBox,int> number=field=>{int value;if(!Int32.TryParse(field.Text,out value))throw new FormatException("Укажите числовой порт подключения.");return value;};if(id=="3xui"){if(options.tcp)options.tcp_port=number(tcpPort);if(options.grpc)options.grpc_port=number(grpcPort);}else if(id=="openflux"&&options.transport=="direct")options.direct_port=number(directPort);else if(id=="swg"){options.vk_calls=readCalls();options.relay_port=number(relayPort);if(options.relay_kind!="csqtt")options.wg_port=number(wgPort);}return options;};
   relayPort.Text=SuggestedDeploymentPort(56000).ToString();wgPort.Text=SuggestedDeploymentPort(51820).ToString();
   return section;
  }
 }
